import boto3
import os

class SecurityClient:
    def __init__(self):
        self.kms_client = boto3.client(
            'kms',
            region_name=os.environ.get('AWS_REGION', 'us-east-1')
        )
        self.comprehend_client = boto3.client(
            'comprehend',
            region_name=os.environ.get('AWS_REGION', 'us-east-1')
        )
        self.translate_client = boto3.client(
            'translate',
            region_name=os.environ.get('AWS_REGION', 'us-east-1')
        )

    def get_kms_client(self):
        return self.kms_client

    def get_comprehend_client(self):
        return self.comprehend_client

    def get_translate_client(self):
        return self.translate_client

import base64
from security_client import SecurityClient
from security_models import EncryptionRequest, EncryptionResponse

def encrypt_payload(request: EncryptionRequest) -> EncryptionResponse:
    kms_client = SecurityClient().get_kms_client()
    response = kms_client.encrypt(
        KeyId=request.key_id,
        Plaintext=request.plaintext.encode('utf-8')
    )
    return EncryptionResponse(
        ciphertext=base64.b64encode(response['CiphertextBlob']),
        key_id=response['KeyId']
    )

import base64
from security_client import SecurityClient
from security_models import DecryptionRequest, DecryptionResponse

def decrypt_payload(request: DecryptionRequest) -> DecryptionResponse:
    kms_client = SecurityClient().get_kms_client()
    decrypt_args = {
        'CiphertextBlob': base64.b64decode(request.ciphertext)
    }
    if request.key_id:
        decrypt_args['KeyId'] = request.key_id

    response = kms_client.decrypt(**decrypt_args)

    return DecryptionResponse(
        plaintext=response['Plaintext'].decode('utf-8'),
        key_id=response['KeyId']
    )
